begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
delete from public.team_members;
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000001001','deposit.edit@example.test');
insert into public.team_members(id,auth_user_id,email,display_name) values('00000000-0000-4000-8000-000000001001','00000000-0000-4000-8000-000000001001','deposit.edit@example.test','Diseño y Finanzas');
insert into public.team_member_roles(member_id,role) values('00000000-0000-4000-8000-000000001001','designer'),('00000000-0000-4000-8000-000000001001','finance'),('00000000-0000-4000-8000-000000001001','operator');
set local role authenticated;
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000001001';
select public.save_customer('00000000-0000-4000-8000-000000001021',null,'{"display_name":"Cliente con seña"}');
select public.create_direct_order('00000000-0000-4000-8000-000000001022','00000000-0000-4000-8000-000000001021',null,null,'','[{"description":"Imanes","quantity":100,"amount":"300"}]','{"amount":"100","paid_on":"1901-01-15","method":"cash"}');
select lives_ok($$select public.edit_order('00000000-0000-4000-8000-000000001022',1,'[{"description":"Imanes nuevos","client_description":"Imanes nuevos","specifications":"Cortar","quantity":500,"amount":"250.50"}]','Nuevo detalle','{}','')$$,'Permite editar ítems con seña');
select is((public.order_money('00000000-0000-4000-8000-000000001022')->>'paid')::numeric,100::numeric,'Seña intacta');
select is((public.order_money('00000000-0000-4000-8000-000000001022')->>'balance')::numeric,150.50::numeric,'Saldo recalculado descontando seña');
select throws_ok($$select public.edit_order('00000000-0000-4000-8000-000000001022',2,'[{"description":"Imanes nuevos","client_description":"Imanes nuevos","specifications":"Cortar","quantity":500,"amount":"99.99"}]','Nuevo detalle','{}','')$$,'23514',null,'No permite total menor que seña');
select is((select total from public.orders where id='00000000-0000-4000-8000-000000001022'),250.50::numeric,'Rechazo revierte total');
select is((select production_revision from public.orders where id='00000000-0000-4000-8000-000000001022'),2,'Rechazo revierte revisión');
select is((select quantity from public.order_items where order_id='00000000-0000-4000-8000-000000001022'),500,'Rechazo conserva ítems');
select lives_ok($$select public.save_order_work_details('00000000-0000-4000-8000-000000001022',2,(select jsonb_agg(jsonb_build_object('id',id,'description',description,'client_description',client_description,'specifications',specifications,'quantity',quantity,'amount',amount)) from public.order_items where order_id='00000000-0000-4000-8000-000000001022'),'Ficha con seña','{}')$$,'También permite editar ficha general con seña');
select lives_ok($$select public.edit_order('00000000-0000-4000-8000-000000001022',3,'[{"description":"Imanes nuevos","client_description":"Imanes nuevos","specifications":"Cortar","quantity":500,"amount":"100"}]','Nuevo detalle','{}','')$$,'Permite total exactamente igual a seña');
select is((public.order_money('00000000-0000-4000-8000-000000001022')->>'balance')::numeric,0::numeric,'Saldo cero permitido');
select throws_ok($$select public.delete_order('00000000-0000-4000-8000-000000001022',4,(select number from public.orders where id='00000000-0000-4000-8000-000000001022'))$$,'23514',null,'Seña sigue impidiendo borrado');
select lives_ok($$select public.edit_order('00000000-0000-4000-8000-000000001022',4,'[{"description":"Imanes nuevos","client_description":"Imanes nuevos","specifications":"Cortar","quantity":500,"amount":"200"}]','Nuevo detalle','{}','')$$,'Permite aumentar total luego');
select public.record_payment('00000000-0000-4000-8000-000000001050','00000000-0000-4000-8000-000000001022',1,'1901-01-15','cash','Cobro posterior');
select throws_ok($$select public.edit_order('00000000-0000-4000-8000-000000001022',5,'[{"description":"Imanes nuevos","client_description":"Imanes nuevos","specifications":"Cortar","quantity":500,"amount":"250"}]','Nuevo detalle','{}','')$$,'23514',null,'Un cobro adicional mínimo bloquea edición');
select throws_ok($$select public.save_order_work_details('00000000-0000-4000-8000-000000001022',5,(select jsonb_agg(jsonb_build_object('id',id,'description',description,'client_description',client_description,'specifications',specifications,'quantity',quantity,'amount',amount)) from public.order_items where order_id='00000000-0000-4000-8000-000000001022'),'Ficha','{}')$$,'23514',null,'Un cobro adicional bloquea ficha');
select ok(not has_function_privilege('authenticated','private.edit_order_before_deposit(uuid,integer,jsonb,text,jsonb,text)','EXECUTE'),'No puede omitir control de total');
select ok(not has_function_privilege('authenticated','private.delete_order_before_deposit(uuid,integer,bigint)','EXECUTE'),'No puede omitir bloqueo de borrado');
reset role;
select * from finish();
rollback;
